test('정규화된SENDroute는서버credential scope와실서명을소비하고최종credential변경뒤재전송하지않는다',async()=>{
 for(const changedAfter of [null,'EXECUTION','CREDENTIAL']){
  const f=await authenticatedInstructionFixture(),p=await f.issue(),credential='av3ex1_'+'s'.repeat(43);let lookups=0,scopeChanged=false;
  const unused=async()=>assert.fail('SEND_ROUTE_MUST_NOT_CALL_OTHER_CONSUMER');
  // 문자열 credential도 메모리 합성 fixture다. 실제 credential 발급·HTTP 리스너는 없다.
  const router=new SyntheticExecutionRequestRouter({transport:'SYNTHETIC_ONLY',clock:()=>new Date(f.clock()).toISOString(),credentials:{transport:'SYNTHETIC_ONLY',current:async input=>{lookups++;assert.equal(input.credential,credential);if(changedAfter&&lookups===2)scopeChanged=true;return{transport:'SYNTHETIC_ONLY',scope:{...f.h.scope,executionGeneration:scopeChanged&&changedAfter==='EXECUTION'?2:1,credentialGeneration:scopeChanged&&changedAfter==='CREDENTIAL'?2:1},checkedAt:new Date(f.clock()).toISOString(),expiresAt:f.h.current.grantExpiresAt,executionAuthorized:false,dispatchPerformed:false};}},permits:instructionPermitSelector(f),observations:{transport:'SYNTHETIC_ONLY',ingest:unused},materials:{transport:'SYNTHETIC_ONLY',readWithDeadline:unused},stopInstructions:{transport:'SYNTHETIC_ONLY',read:unused}});
  const raw={method:'POST',path:p.proof.path,query:[],bodyRaw:p.raw,cookie:null,credential,challengeRef:p.issued.ref,proof:p.proof,signature:p.signature};
  for(const invalid of [{...raw,cookie:'synthetic-cookie'},{...raw,credential:'av3er1_'+'s'.repeat(43)}])await assert.rejects(router.handle(invalid),/EXECUTION_REQUEST_REJECTED/);
  assert.equal(lookups,0);assert.equal(f.state().permits.length,0);
  if(changedAfter){await assert.rejects(router.handle(raw),/EXECUTION_REQUEST_REJECTED/);assert.equal(f.state().permits.length,1);assert.equal(f.state().results.length,1);const count=f.connections();await assert.rejects(router.handle(raw),/EXECUTION_REQUEST_REJECTED/);assert.equal(f.connections(),count+(changedAfter==='EXECUTION'?1:0));assert.equal(f.state().permits.length,1);assert.equal(f.state().results.length,1);}
  else{const first=await router.handle(raw);assert.equal(first.cacheControl,'no-store');assert.equal(first.data.permit.envelopeHash,f.h.request.envelopeHash);assert.equal(first.data.nonceConsumed,true);assert.equal(first.dispatchPerformed,false);assert.deepEqual(await router.handle(raw),first);assert.equal(f.state().permits.length,1);assert.equal(f.state().results.length,1);}
 }
});
